WHERE authored_id = $q$NG-ORIGINAL-CLINICAL-0068$q$;

UPDATE questions SET
  choices = $q$[{"id": "a", "text": "An administrative assistant who uses a sit-stand desk"}, {"id": "b", "text": "A warehouse clerk who walks briskly for forty minutes daily"}, {"id": "c", "text": "A fitness instructor with a normal body mass index"}, {"id": "d", "text": "A long-distance haulage driver who drives ten hours a day and unloads the truck alone"}]$q$::jsonb,
  correct_choice_id = $q$d$q$,
  rationale = $q$Long-distance driving combines prolonged static lumbar flexion, whole-body vibration from the vehicle and repeated heavy manual unloading, three independent risks that compound over a working life. Option B describes regular moderate activity, which is protective. Option C describes a fit worker with occupational activity and normal weight. Option A describes a workplace adaptation that specifically reduces sitting exposure.$q$,
