UPDATE questions SET
  choices = $q$[{"id": "a", "text": "The patient may bend and twist freely straight after fusion"}, {"id": "b", "text": "Patients need no analgesia after fusion"}, {"id": "c", "text": "Fusion pain is confined to the lower limbs"}, {"id": "d", "text": "The iliac crest donor site is often more painful than the spinal incision itself"}]$q$::jsonb,
  correct_choice_id = $q$d$q$,
  rationale = $q$Harvesting bone from the iliac crest splits muscle and periosteum, both richly innervated, so the donor site frequently hurts more than the spinal wound and can be missed if the nurse only assesses the back. Analgesia must cover both sites, and the nurse should ask about the hip. Option B would leave the patient in severe unmanaged pain. Option C confuses radicular pain with the wound. Option A risks disrupting the fusion, which is why movement restrictions are enforced.$q$,
  strategy = $q$After a fusion with a graft, ask about the hip as well as the back. The graft site hurts more.$q$
WHERE authored_id = $q$NG-ORIGINAL-CLINICAL-0071$q$;

UPDATE questions SET
  choices = $q$[{"id": "a", "text": "Walk barefoot on hard floors as soon as possible"}, {"id": "b", "text": "Soak both feet in hot water three times daily"}, {"id": "c", "text": "Rest often with both feet elevated above the level of the heart"}, {"id": "d", "text": "Apply continuous warm compresses over the dressings"}]$q$::jsonb,
  correct_choice_id = $q$c$q$,
  rationale = $q$Elevation above heart level lets gravity and the venous and lymphatic pumps clear the oedema from the feet, which reduces throbbing pain and tension on the suture line. Option B increases swelling and heat and softens the tissue that needs to heal. Option A loads the operated forefoot and increases bleeding and pain. Option D adds warmth and moisture to a fresh wound, promoting oedema and infection.$q$,
  strategy = $q$Feet up, above the heart, as often as possible in the first days.$q$
WHERE authored_id = $q$NG-ORIGINAL-CLINICAL-0072$q$;

UPDATE questions SET
  choices = $q$[{"id": "a", "text": "Withholding all oral fluids for 24 hours"}, {"id": "b", "text": "Immediate administration of broad-spectrum oral antibiotics"}, {"id": "c", "text": "Prescription of antimotility agents such as loperamide"}, {"id": "d", "text": "Timely fluid and electrolyte rehydration with oral rehydration solution"}]$q$::jsonb,
  correct_choice_id = $q$d$q$,
