WHERE authored_id = $q$NG-ORIGINAL-CLINICAL-0074$q$;

UPDATE questions SET
  choices = $q$[{"id": "a", "text": "Extensive surface road abrasions with embedded gravel"}, {"id": "b", "text": "Deep contaminated puncture wounds from animal bites"}, {"id": "c", "text": "Clean surgical or sharp incisional wounds"}, {"id": "d", "text": "Severe jagged soft-tissue lacerations with crushed margins"}]$q$::jsonb,
  correct_choice_id = $q$c$q$,
  rationale = $q$Clean incisional wounds created by sharp edges have well-approximated linear borders, minimal devitalized tissue, and minimal dirt contamination, yielding the lowest infection rates compared to punctures, abrasions, and crush lacerations.$q$,
  strategy = $q$Clean sharp margins with minimal tissue trauma heal best; jagged, crushed, or contaminated wounds carry much higher infection risk.$q$
WHERE authored_id = $q$NG-ORIGINAL-CLINICAL-0075$q$;

UPDATE questions SET
  choices = $q$[{"id": "a", "text": "The colour of the dressing applied"}, {"id": "b", "text": "The patient's age alone"}, {"id": "c", "text": "The time of day the wound was made"}, {"id": "d", "text": "The depth and size of the divided vessels"}]$q$::jsonb,
  correct_choice_id = $q$d$q$,
  rationale = $q$Bleeding is a hydraulic problem: deeper and wider wounds divide larger arteries, arterioles and veins, and vessels divided nearer their origin are at higher pressure, so they bleed faster and in greater volume. Option B modifies healing and tolerance but not the mechanics of the vessel. Option C has no physiological effect. Option A affects what you can see on the dressing, not how much the wound is losing.$q$,
  strategy = $q$Bleeding follows the anatomy: bigger vessel, higher pressure, faster loss.$q$
WHERE authored_id = $q$NG-ORIGINAL-CLINICAL-0076$q$;

UPDATE questions SET
  choices = $q$[{"id": "a", "text": "Clean incisional wounds"}, {"id": "b", "text": "Superficial abrasions only"}, {"id": "c", "text": "Puncture wounds with potential crush-laceration injury"}, {"id": "d", "text": "Non-penetrating closed contusions"}]$q$::jsonb,
