UPDATE questions SET
  choices = $q$[{"id": "a", "text": "Coeliac disease, an autoimmune reaction to dietary gluten"}, {"id": "b", "text": "Phenylketonuria (PKU), an inborn error of amino-acid metabolism"}, {"id": "c", "text": "Glucose-6-phosphate dehydrogenase (G6PD) deficiency"}, {"id": "d", "text": "Homocystinuria, an inborn error of methionine metabolism"}]$q$::jsonb,
