UPDATE questions SET
  choices = $q$[{"id": "a", "text": "High urine osmolality with concentrated brown appearance"}, {"id": "b", "text": "Abnormally high urine specific gravity (greater than 1.035)"}, {"id": "c", "text": "Heavy 4+ proteinuria with red blood cell casts"}, {"id": "d", "text": "Very low urine specific gravity (less than 1.005)"}]$q$::jsonb,
  correct_choice_id = $q$d$q$,
  rationale = $q$Diabetes insipidus results from deficient secretion of antidiuretic hormone (ADH). Without ADH, renal collecting ducts cannot reabsorb free water, resulting in copious excretion of dilute urine with a characteristically low specific gravity (typically 1.001 to 1.005).$q$,
  strategy = $q$Diabetes Insipidus (DI) = Dilute urine. Deficient ADH leads to massive water excretion, resulting in low urine specific gravity (< 1.005) and high serum osmolality.$q$
WHERE authored_id = $q$NG-ORIGINAL-CLINICAL-0082$q$;

UPDATE questions SET
  choices = $q$[{"id": "a", "text": "Increased serum calcium with decreased serum phosphate"}, {"id": "b", "text": "Decreased serum calcium with increased serum phosphate"}, {"id": "c", "text": "Decreased serum calcium with decreased serum phosphate"}, {"id": "d", "text": "Normal serum calcium with elevated alkaline phosphatase only"}]$q$::jsonb,
  correct_choice_id = $q$b$q$,
  rationale = $q$Parathyroid hormone (PTH) normally increases serum calcium and promotes renal excretion of phosphate. Deficient PTH leads to hypocalcemia (causing neuromuscular irritability, tetany, Chvostek's/Trousseau's signs) and hyperphosphatemia (high phosphate).$q$,
  strategy = $q$Remember the seesaw rule: Calcium and Phosphate have an inverse relationship in parathyroid disease. Hypoparathyroidism = Low Calcium, High Phosphate.$q$
WHERE authored_id = $q$NG-ORIGINAL-CLINICAL-0083$q$;

UPDATE questions SET
  choices = $q$[{"id": "a", "text": "Hyperpigmentation of palmar creases and scars"}, {"id": "b", "text": "Postural hypotension and dizziness"}, {"id": "c", "text": "Hirsutism and central moon face"}, {"id": "d", "text": "Hypoglycemia and chronic fatigue"}]$q$::jsonb,
  correct_choice_id = $q$c$q$,
  rationale = $q$Addison's disease is primary adrenal failure characterized by deficiency of glucocorticoids, mineralocorticoids, and androgens. Signs include hypotension, hypoglycemia, weight loss, and bronze hyperpigmentation. Hirsutism and moon facies indicate Cushing's syndrome (excess cortisol/androgens).$q$,
