UPDATE questions SET
  choices = $q$[{"id": "a", "text": "Enlargement of the frontal skull bones"}, {"id": "b", "text": "Bowing of the weight-bearing tibia and femur"}, {"id": "c", "text": "Radiographic evidence of basilar invagination with cranial nerve deficits"}, {"id": "d", "text": "Mild asymmetric warmth over the anterior lower leg"}]$q$::jsonb,
